    // DW-1.4 — food rows carry the DefaultToFood shape; the epilogue
    // rules are visible in the data.
    #[test]
    fn test_DW_1_4_food_and_epilogue_rules_present() {
        // IsFood ids (ItemID.cs:498, 86 of them): SetFoodDefaults
        // (DefaultToFood) or, for case-less 4010, the stock shape + holdStyle 1.
        let food = [353, 357, 967, 969, 1787, 1911, 1912, 1919, 1920, 2266, 2267, 2268, 2425, 2426, 2427, 3195, 3532, 4009, 4010, 4011, 4012, 4013, 4014, 4015, 4016, 4017, 4018, 4019, 4020, 4021, 4022, 4023, 4024, 4025, 4026, 4027, 4028, 4029, 4030, 4031, 4032, 4033, 4034, 4035, 4036, 4037, 4282, 4283, 4284, 4285, 4286, 4287, 4288, 4289, 4290, 4291, 4292, 4293, 4294, 4295, 4296, 4297, 4403, 4411, 4614, 4615, 4616, 4617, 4618, 4619, 4620, 4621, 4622, 4623, 4624, 4625, 5009, 5041, 5042, 5092, 5093, 5275, 5277, 5278, 5537, 5645];
        assert_eq!(food.len(), 86);
        // 4010 is Deprecated (ItemID.cs:1316) — TurnToAir zeroes it
        // (Item.cs:48921-48924); the epilogue holdStyle never applies.
        assert!(same_except_id(&ITEMS[4010], &ITEMS[0]));
        for &id in &food {
            if id == 4010 { continue; }
            let d = &ITEMS[id as usize];
            assert_eq!(d.hold_style, 1, "id {id}"); // Item.cs:48913-48916
            if id != 4010 {
                // DefaultToFood — Item.cs:48541-48568
                assert!(d.consumable, "id {id}");
                assert!(d.use_turn, "id {id}");
                assert_eq!((d.use_time, d.use_animation), (17, 17), "id {id}");
                // rare/value come from the per-id SetShopValues call —
                // the DefaultToFood stock (rare 1, buyPrice(0,0,20) = 2000) is
                // overridden for most foods, so only the timings pin here.
            }
        }
        // bait rare ladder — Item.cs:48838-48852: bait >= 50 → rare 3
        for &id in &[1999, 2673, 2676, 2891, 2893, 2895, 4340, 4362, 4419] {
            assert_eq!(ITEMS[id as usize].rare, 3, "id {id}");
        }
        // 1803-1807 redirect — Item.cs:48917-48920: rows equal 1533-1537's
        for k in 0..5 {
            assert!(same_except_id(&ITEMS[1803 + k], &ITEMS[1533 + k]), "redirect {k}");
        }
        // deprecated ids → TurnToAir ⇒ the id-0 row — Item.cs:48921-48924, :49884-48990
        for &id in &[2772, 2773, 2775, 2777, 2778, 2780, 2782, 2783, 2785, 2881, 3462, 3463, 3465, 3847, 3848, 3849, 3850, 3851, 3861, 3862, 3978, 4010, 4058, 4722, 6143, 6160, 6170, 6171] {
            assert!(same_except_id(&ITEMS[id as usize], &ITEMS[0]), "deprecated {id}");
        }
    }

