    #[test]
    fn test_DW_1_2_negative_defaults_and_on_created() {
        assert_eq!(NEGATIVE_DEFAULTS.len(), 48);
        assert_eq!(NEGATIVE_DEFAULTS[47], (-1, 3521)); // Item.cs:1217-1219
        assert_eq!(NEGATIVE_DEFAULTS[0], (-48, 3480)); // Item.cs:1358-1360
        assert_eq!(ON_CREATED, &[(5437, 5358)]); // Item.cs:48936-48942
    }

    // DW-1.2 — the ItemVariants tables (25 registrations + delta rows).
    #[test]
    fn test_DW_1_2_variant_tables() {
        let regs: Vec<_> = VARIANT_OVERRIDES
            .iter()
            .filter(|r| r.condition.is_some())
            .collect();
        assert_eq!(regs.len(), 25); // ItemVariants.cs:121-145
        let deltas: Vec<_> = VARIANT_OVERRIDES
            .iter()
            .filter(|r| r.condition.is_none())
            .collect();
        assert_eq!(deltas.len(), 25);
        // 112 Stronger — Item.cs:2716-2723
        let r112 = deltas
            .iter()
            .find(|r| r.id == 112 && r.variant == ItemVariant::Stronger)
            .unwrap();
        assert!(r112.set.contains(&VOp::Set(VField::Rare, VVal::Int(6))));
        assert!(r112.set.contains(&VOp::Set(VField::Value, VVal::Int(500000))));
        assert!(r112.set.contains(&VOp::Set(VField::Damage, VVal::Int(85))));
        assert!(r112.set.contains(&VOp::Set(VField::UseAnimation, VVal::Int(12))));
        assert!(r112.set.contains(&VOp::Set(VField::UseTime, VVal::Int(12))));
        // 544 DisabledBossSummon loses the use block — Item.cs:7873-7880
        let r544 = deltas
            .iter()
            .find(|r| r.id == 544 && r.variant == ItemVariant::DisabledBossSummon)
            .unwrap();
        assert!(r544.set.contains(&VOp::Set(VField::UseStyle, VVal::Int(0))));
        assert!(r544.set.contains(&VOp::Set(VField::Consumable, VVal::Bool(false))));
        // the base row keeps the use block (the branch applies without the variant)
        assert_eq!(ITEMS[544].use_style, 4);
        assert!(ITEMS[544].consumable);
    }

    // DW-1.2 — names come from the ItemID consts.
    #[test]
    fn test_DW_1_2_names() {
        assert_eq!(NAMES.len(), 6196);
        assert_eq!(NAMES[0], "None");
        assert_eq!(NAMES[2], "DirtBlock");
        assert_eq!(NAMES[6195], "OldStyleParkourBookInactive");
        assert_eq!(ITEMS[2].name, "Dirt Block");
    }
